def test_oracle_prompt_omits_memory_context_for_zip_attach(tmp_path: pathlib.Path) -> None:
    from ask.webgpt_runtime import build_webgpt_oracle_prompt

    archive = tmp_path / "review-bundle.zip"
    with zipfile.ZipFile(archive, "w") as zf:
        zf.writestr("REVIEW_REQUEST.md", "# Review\n")
    question = f"Review {archive} and return VERDICT: PASS."
    attachments = extract_file_attachments(question)
    attach_file = resolve_web_review_delivery(question, attachments, backend="webgpt")
    huge_memory = "MEMORY_CONTEXT " * 200_000
    prompt = build_webgpt_oracle_prompt(
        huge_memory,
        question,
        attachments,
        attach_file=attach_file,
    )
    assert huge_memory not in prompt
    assert "MEMORY_CONTEXT" not in prompt
    assert "VERDICT" in prompt
    assert len(prompt.encode("utf-8")) < 10_000


