def test_call_webgpt_passes_url_for_explicit_tab_and_url(
    tmp_path: pathlib.Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    surf = tmp_path / "surf"
    surf.write_text("#!/bin/sh\n", encoding="utf-8")
    surf.chmod(0o755)
    captured: dict[str, list[str]] = {}

    class _Result:
        returncode = 0
        stdout = ""
        stderr = ""

    def fake_run(cmd, **kwargs):
        if "webgpt.preflight" in cmd:
            captured["preflight_cmd"] = list(cmd)
            result = _Result()
            result.stdout = json.dumps(
                {
                    "status": "pass",
                    "failures": [],
                    "requested_tab_id": "837346844",
                }
            )
            return result
        captured["cmd"] = list(cmd)
        output = pathlib.Path(cmd[cmd.index("--output") + 1])
        raw_output = pathlib.Path(cmd[cmd.index("--raw-output") + 1])
        meta_output = pathlib.Path(cmd[cmd.index("--meta-output") + 1])
        sentinel = "<<<WEBGPT_DONE:test>>>"
        output.write_text("VERDICT: PASS\n", encoding="utf-8")
        raw_output.write_text(f"VERDICT: PASS\n{sentinel}\n", encoding="utf-8")
        meta_output.write_text(
            json.dumps(
                {
                    "status": "completed",
                    "sentinel": sentinel,
                    "controlled_tab_id": "837346844",
                    "requested_tab_id": "837346844",
                    "requested_url": "https://chatgpt.com/c/example",
                    "raw_contains_sentinel": True,
                    "clean_contains_sentinel": False,
                    "no_activate": True,
                    "focus_changed": False,
                }
            ),
            encoding="utf-8",
        )
        return _Result()

    monkeypatch.setattr("ask.webgpt_runtime.check_and_record", lambda: None)
    monkeypatch.setattr("subprocess.run", fake_run)

    call_webgpt(
        "Review this.",
        tab_id="837346844",
        url="https://chatgpt.com/c/example",
        surf_run=surf,
        artifact_dir=tmp_path / "artifacts",
    )

    cmd = captured["cmd"]
    preflight_cmd = captured["preflight_cmd"]
    assert "webgpt.preflight" in preflight_cmd
    assert "--tab-id" in preflight_cmd
    assert preflight_cmd[preflight_cmd.index("--tab-id") + 1] == "837346844"
    assert "--expect-url" in preflight_cmd
    assert preflight_cmd[preflight_cmd.index("--expect-url") + 1] == "https://chatgpt.com/c/example"
    assert "--no-activate" in preflight_cmd
    assert "--tab-id" in cmd
    assert cmd[cmd.index("--tab-id") + 1] == "837346844"
    assert "--expect-url" in cmd
    assert cmd[cmd.index("--expect-url") + 1] == "https://chatgpt.com/c/example"
    assert "--url" not in cmd


def test_call_webgpt_fails_on_browser_oracle_missing_binding(
    tmp_path: pathlib.Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    surf = tmp_path / "surf"
    surf.write_text("#!/bin/sh\n", encoding="utf-8")
    surf.chmod(0o755)

    def fake_browser_oracle(**kwargs):
        return (
            "demo-project",
            "",
            "",
            {
                "status": "needs_attention",
                "reason": "binding_missing",
                "project": "demo-project",
                "browser_oracle_applied": True,
            },
        )

    def fake_run(cmd, **kwargs):
        raise AssertionError(f"surf should not run after browser-oracle failure: {cmd}")

    monkeypatch.setattr("ask.webgpt_runtime.apply_webgpt_browser_oracle", fake_browser_oracle)
